import React, { useState } from 'react';
import { searchTracks } from '../services/api';

const TrackSearch = ({ onTrackSelected }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filteredTracks, setFilteredTracks] = useState([]);

  const handleSearch = async () => {
    console.log('Search button clicked!'); // Add this debug line
    console.log('Search term:', searchTerm); // Log the search term
    try {
      const results = await searchTracks(searchTerm);
      console.log('Search results:', results); // Log the search results
      setFilteredTracks(results);
    } catch (error) {
      console.error('Error during search:', error); // Log any error that occurs
    }
  };

  return (
    <div>
      <input
        type="text"
        placeholder="Search for a track..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
      />
      <button onClick={handleSearch}>Search</button>
      <div>
        {filteredTracks.length > 0 ? (
          <ul>
            {filteredTracks.map((track) => (
              <li key={track.id} onClick={() => onTrackSelected(track)}>
                {track.title} - {track.artist.name}
              </li>
            ))}
          </ul>
        ) : (
          <p>No results found</p>
        )}
      </div>
    </div>
  );
};

export default TrackSearch;
